const releaseConfig=globalThis.DECKOMANTIK_RELEASE||{extensions:{}};
const extensionEnabled=id=>id==='beta'||releaseConfig.extensions?.[id]===true;
const sourceCardSets=globalThis.DECKOMANTIK_CARD_SETS||[{id:'beta',code:'BETA',name:'Beta',cardCount:(globalThis.DECKOMANTIK_CARDS||[]).length}];
const cardSets=sourceCardSets.filter(set=>extensionEnabled(set.id));
const setById=new Map(cardSets.map(set=>[set.id,set]));
const betaCards=(globalThis.DECKOMANTIK_CARDS||[]).map(card=>({...card,setId:card.setId||'beta',setNumber:Number(card.setNumber)||Number(card.collectionNumber),collectorCode:card.collectorCode||`BETA-${String(card.collectionNumber).padStart(3,'0')}`}));
const cards=[...betaCards,...(globalThis.DECKOMANTIK_INNER_DESERTS_CARDS||[]).filter(card=>extensionEnabled(card.setId||'inner-deserts'))];
const sourceBoosterProducts=globalThis.DECKOMANTIK_BOOSTERS||[{id:'beta',name:'Beta',image:'assets/booster-pack-cover.png',slots:[{setId:'beta',count:5}],desertChance:0,guarantee:'silver'}];
const boosterProducts=sourceBoosterProducts.filter(product=>(product.slots||[]).every(slot=>extensionEnabled(slot.setId||'beta')));
const boosterById=new Map(boosterProducts.map(product=>[product.id,product]));
const innerDesertsEnabled=extensionEnabled('inner-deserts');
const normalizeSelectedSetIds=value=>{const known=new Set(cardSets.map(set=>set.id)),selected=Array.isArray(value)?value.filter(id=>known.has(id)):[];return selected.length?selected:[...known]};
const rulesData=globalThis.DECKOMANTIK_RULES||{pageCount:0,chapters:[],terms:[],sources:{}};
const ruleTermsById=new Map((rulesData.terms||[]).map(term=>[term.id,term]));
const byId=new Map(cards.map(card=>[card.id,card]));
const cardIndexById=new Map(cards.map((card,index)=>[card.id,index]));
const cardByNumber=new Map(betaCards.map(card=>[Number(card.collectionNumber),card]));
const cardByCollectorCode=new Map(cards.map(card=>[String(card.collectorCode||'').toUpperCase(),card]));
