const clone=value=>JSON.parse(JSON.stringify(value));
const uniqueId=()=>`deck-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const storedCardId=value=>typeof value==='string'&&value.length<=160&&/^[a-z0-9][a-z0-9_-]*$/i.test(value);
const presetGroupKinds=['manifestations','volontes','sideboard','maybeboard'];
const presetGroupLabels={fr:{manifestations:'Manifestations',volontes:'Volontés',sideboard:'Sideboard',maybeboard:'Maybeboard'},en:{manifestations:'Manifestations',volontes:'Wills',sideboard:'Sideboard',maybeboard:'Maybeboard'},it:{manifestations:'Manifestazioni',volontes:'Volontà',sideboard:'Sideboard',maybeboard:'Maybeboard'}};
const normalizedPresetName=value=>String(value||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'').trim();
function inferGroupKind(group){const explicit=String(group?.kind||group?.id||'').toLowerCase();if(presetGroupKinds.includes(explicit))return explicit;const name=normalizedPresetName(group?.name);if(name==='manifestations'||name==='manifestazioni')return'manifestations';if(name==='wills'||name==='volontes'||name==='volonta')return'volontes';if(name==='sideboard'||name==='sidedeck')return'sideboard';if(name==='maybeboard')return'maybeboard';return null}
function localizedGroupName(group){const kind=inferGroupKind(group);if(!kind)return group?.name||'';const isUntouchedPreset=Object.values(presetGroupLabels).some(labels=>normalizedPresetName(labels[kind])===normalizedPresetName(group?.name));return isUntouchedPreset?(presetGroupLabels[language]?.[kind]||presetGroupLabels.en[kind]):group.name}
function isMaybeboardGroup(group){return inferGroupKind(group)==='maybeboard'}
function isSideboardGroup(group){return inferGroupKind(group)==='sideboard'}
function isExcludedDeckGroup(group){return isMaybeboardGroup(group)||isSideboardGroup(group)}
