function matchesNumericFilter(value,selected){return selected==='all'||(selected==='none'?(value===null||value===undefined):String(value)===selected)}
const normalizeSearch=value=>String(value??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
