const normalizeName=value=>value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/^\s*(?:[-*•]+|\d+[.)])\s*/,'').replace(/^\s*\d+\s*[x×]\s*/i,'').replace(/^\s*#\d+\s*[-–—.:]?\s*/,'').replace(/[^a-z0-9]+/g,' ').trim();
