function parseKartomantikBuilderUrl(text){
  let url;try{url=new URL(String(text||'').trim())}catch{return null}
  const host=url.hostname.toLowerCase().replace(/^www\./,'');
  const pathMatch=url.pathname.match(/^\/(en|it)\/builder\/?$/i);
  if(host!=='kartomantik.com'||!pathMatch)return null;
  const cardIds=(url.searchParams.get('cards')||'').split(',').map(id=>id.trim().toLowerCase()).filter(Boolean);
  return {deckName:(url.searchParams.get('name')||'').trim(),cardIds,language:pathMatch[1].toLowerCase()};
}
