function syncGlobalsFromStore(){language=store.settings.language;theme=store.settings.theme;accent=accents.includes(store.settings.accent)?store.settings.accent:DEFAULT_ACCENT;librarySize=store.settings.librarySize;libraryWidth=store.settings.libraryWidth;drawSize=store.settings.drawSize;advancedFiltersCollapsed=store.settings.advancedFiltersCollapsed;libraryControlsCollapsed=store.settings.libraryControlsCollapsed;mobileLibraryControlsHeight=store.settings.mobileLibraryControlsHeight}
