  if(event.key!==STORE_KEY)return;
  const incoming=remoteStoreFrom(event.newValue);if(!incoming)return;
  if(isEditingTarget(document.activeElement)||hasPendingLocalWrites()){pendingRemoteSync=incoming;return}
